package com.example.examplemod.cargo.center;

import com.example.examplemod.city.CityManager;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import java.util.*;

/** Authoritative OP editor and public contract workflow for the logistics center. */
public final class MasterCityCenter {
    private MasterCityCenter(){}
    public static boolean handles(String action){return action.startsWith("MASTER_")||action.equals("CONTRACT_SUPPLY");}
    public static CompoundTag quoteSupply(ServerPlayer actor,UUID selected,CompoundTag values){return MasterCityTradeService.quoteSupply(actor,selected,values);}
    public static CompoundTag snapshot(ServerPlayer actor,CompoundTag q){boolean admin=q.getString("Section").equals("master_city");if(admin)MasterCityTradeService.requireOp(actor);var s=actor.getServer();MasterCityTradeService.clock(s);var b=MasterCityTradeService.book(s);var data=new CompoundTag();data.putString("Section",admin?"master_city":"trade_contracts");var all=new ArrayList<CompoundTag>();var choices=new CompoundTag();var warehouses=new ListTag();var cities=new ListTag();
        for(var city:CityManager.get(s.overworld()).getCities())if(admin)option(cities,city.getId().toString(),city.getName());
        for(var w:CargoWarehouseRegistry.get(s).all())if(admin||MasterCityTradeService.maySupply(actor,w))option(warehouses,w.id().toString(),w.name()+" · "+CargoWarehouseRegistry.access(s,w).owner().name(s));choices.put("MasterCities",cities);choices.put("MasterWarehouses",warehouses);choices.put("Warehouses",warehouses.copy());
        if(admin){var row=row(MasterCityTradeService.stable("settings"),"master_settings","Внешняя торговля Моржеграда",b.enabled()?"CONFIGURED":"DISABLED","Сутки: Europe/Minsk · осталось "+b.remainingBudget()+" CR");row.putBoolean("Enabled",b.enabled());row.putString("Budget",Long.toString(b.dailyBudget()));var details=new ListTag();detail(details,"Суточный бюджет",b.dailyBudget()+" CR");detail(details,"Выделено контрактам",b.allocated()+" CR");detail(details,"Доступно для новых контрактов",b.remainingBudget()+" CR");detail(details,"В ограниченном счёте",b.balance()+" CR");detail(details,"Оплачено по поставкам",b.paid()+" CR");detail(details,"Возвращено в escrow",b.refunded()+" CR");detail(details,"Выведено продажами импорта",b.importRevenue()+" CR");detail(details,"Создано импортом",Long.toString(b.createdUnits()));detail(details,"Физически принято по контрактам",Long.toString(b.receivedUnits()));if(b.binding()!=null){var city=CityManager.get(s.overworld()).getCity(b.binding().city());detail(details,"Город",city==null?"Удалён":city.getName());detail(details,"Склад",CargoWarehouseRegistry.get(s).find(b.binding().warehouse()).map(CargoWarehouseRegistry.Warehouse::name).orElse("Удалён"));row.put("Location",b.binding().buffer().save());try{MasterCityTradeService.warehouse(s);var buffer=MasterCityTradeService.buffer(s);detail(details,"Таможенный буфер",buffer.buffer().locked()?"Заблокирован до сверки партии":"Доступен автоматике");}catch(IllegalArgumentException invalid){detail(details,"Диагностика",Objects.toString(invalid.getMessage(),"Недоступно"));}}else detail(details,"Подключение","Выберите город/склад, глядя на таможенный буфер");for(var a:b.audit().stream().skip(Math.max(0,b.audit().size()-12)).toList())detail(details,a.action(),a.detail());row.put("Facts",details);all.add(row);
            for(var p:b.policies()){var r=row(p.id(),"master_policy",p.name(),p.direction()==MasterCityTradeBook.Direction.OFF?"DISABLED":"CONFIGURED",p.direction()+" · лимит "+b.quotaUsed(p.id())+"/"+p.dailyQuota());r.putString("Name",p.name());var type=ItemStack.parseOptional(s.registryAccess(),p.item());r.putString("Item",type.isEmpty()?"":BuiltInRegistries.ITEM.getKey(type.getItem()).toString());r.putString("Direction",p.direction().name());r.putString("Target",Integer.toString(p.target()));r.putString("Maximum",Integer.toString(p.maximumStock()));r.putString("Batch",Integer.toString(p.batch()));r.putString("Quota",Integer.toString(p.dailyQuota()));r.putString("Price",Long.toString(p.buyPrice()));r.putString("SellPrice",Long.toString(p.sellPrice()));r.putString("DispatchFee",Long.toString(p.maximumFreight()));r.putString("Automatic",Boolean.toString(p.automatic()));r.putString("Partner",p.partner());r.putString("DelayMinutes",Long.toString(p.delayMillis()/60_000));r.putString("DurationHours",Long.toString(p.durationMillis()/3_600_000));var d=new ListTag();detail(d,"Целевой/максимальный запас",p.target()+" / "+p.maximumStock());detail(d,"Закупка/продажа",p.buyPrice()+" / "+p.sellPrice()+" CR");detail(d,"Входящие поставки",Integer.toString(b.inbound(p.id())));try{detail(d,"Физический остаток",Integer.toString(MasterCityTradeService.stock(s,MasterCityTradeService.warehouse(s),type)));}catch(IllegalArgumentException invalid){detail(d,"Физический остаток","Склад недоступен");}r.put("Facts",d);all.add(r);}
            for(var batch:b.imports()){var r=row(batch.id(),"master_import",b.policy(batch.policy()).map(MasterCityTradeBook.Policy::name).orElse("?")+" · ×"+batch.quantity(),batch.state()==MasterCityTradeBook.ImportState.CONFIRMED?"COMPLETED":batch.state()==MasterCityTradeBook.ImportState.ABANDONED?"DISABLED":"RECONCILE","");r.putInt("Quantity",batch.quantity());r.put("Facts",importFacts(batch));r.put("Location",batch.buffer().save());all.add(r);}}
        for(var c:b.contracts())if(admin||c.state()==MasterCityTradeBook.ContractState.OPEN&&b.contractRemaining(c)>0&&c.expires()>b.now()){var r=row(c.id(),"trade_contract",c.name(),c.state()==MasterCityTradeBook.ContractState.OPEN?(b.enabled()?"QUEUED":"DISABLED"):c.state()==MasterCityTradeBook.ContractState.EXPIRED?"EXPIRED":"COMPLETED",b.contractRemaining(c)+" / "+c.quantity()+" шт. · "+c.price()+" CR/шт.");r.putLong("Price",c.price());r.putInt("Remaining",b.contractRemaining(c));var d=new ListTag();detail(d,"Физический получатель","Склад Моржеграда; товар остаётся собственностью города");detail(d,"Оплата перевозки","Из выделенного бюджета контракта, в пределах резерва");detail(d,"Срок",java.time.Instant.ofEpochMilli(c.expires()).atZone(java.time.ZoneId.of("Europe/Minsk")).toLocalDateTime().toString());if(admin)detail(d,"Остаток бюджета",b.contractAvailable(c)+" CR");r.put("Facts",d);all.add(r);}
        String search=q.getString("Search").toLowerCase(Locale.ROOT);all.removeIf(r->!r.getString("Name").toLowerCase(Locale.ROOT).contains(search));all.sort(Comparator.comparing(r->r.getString("Name")));data.putInt("Total",all.size());int page=Math.max(0,Math.min(q.getInt("Page"),Math.max(0,(all.size()-1)/32)));data.putInt("Page",page);var rows=new ListTag();for(int i=page*32;i<Math.min(all.size(),page*32+32);i++)rows.add(all.get(i));data.put("Rows",rows);data.put("Choices",choices);CompoundTag selected=null;if(q.hasUUID("Selected"))for(var r:all)if(r.getUUID("Id").equals(q.getUUID("Selected")))selected=r;var forms=new ListTag();if(admin){CenterForms.add(forms,"MASTER_BIND",false,"City@MasterCities","Warehouse@MasterWarehouses");CenterForms.add(forms,"MASTER_BUDGET",false,"Budget#0");CenterForms.add(forms,"MASTER_TOGGLE",false,"Enabled=true|false");CenterForms.add(forms,"MASTER_RUN",false);if(selected==null||!selected.getString("Kind").equals("master_import"))CenterForms.add(forms,"MASTER_POLICY",selected!=null&&selected.getString("Kind").equals("master_policy"),"Name","Item","Direction=OFF|IMPORT|EXPORT|BOTH","Target#0","Maximum#4096","Batch#64","Quota#256","Price#1","SellPrice#2","DispatchFee#0","Automatic=false|true","Partner","DelayMinutes#60","DurationHours#24");if(selected!=null&&selected.getString("Kind").equals("master_import")){var batch=b.importBatch(selected.getUUID("Id")).orElseThrow();if(batch.state()==MasterCityTradeBook.ImportState.CONFIRMED)CenterForms.add(forms,"MASTER_IMPORT_CLOSE",true);else{CenterForms.add(forms,"MASTER_IMPORT_RECONCILE",true);CenterForms.add(forms,"MASTER_IMPORT_ABANDON",true,"Reason");}}}if(admin&&selected!=null&&selected.getString("Kind").equals("trade_contract"))CenterForms.add(forms,"MASTER_CONTRACT_CLOSE",true);if(selected!=null&&selected.getString("Kind").equals("trade_contract")&&selected.getString("Status").equals("QUEUED"))CenterForms.add(forms,"CONTRACT_SUPPLY",true,"Source@Warehouses","Quantity#1","Preference=CHEAPEST|NO_TOLLS|FASTEST|FEWEST_TRANSFERS","Service=ANY|CHARTER|REGULAR");decorateForms(forms);data.put("Forms",forms);if(selected!=null)data.put("SelectedRow",selected);data.putBoolean("Implemented",true);return data;
    }
    public static void execute(ServerPlayer actor,CompoundTag q){String action=q.getString("Action");if(action.startsWith("MASTER_"))MasterCityTradeService.requireOp(actor);if(!q.hasUUID("Request"))throw new IllegalArgumentException("master_request_required");if(!q.getBoolean("Confirmed"))throw new IllegalArgumentException("master_confirmation_required");var s=actor.getServer();MasterCityTradeService.clock(s);var b=MasterCityTradeService.book(s);var v=q.getCompound("Values");switch(action){
        case "MASTER_BIND"->MasterCityTradeService.bind(actor,id(v,"City"),id(v,"Warehouse"));
        case "MASTER_BUDGET"->b.configureBudget(number(v,"Budget"),actor.getUUID());
        case "MASTER_TOGGLE"->{boolean enable=Boolean.parseBoolean(v.getString("Enabled"));if(enable){MasterCityTradeService.warehouse(s);MasterCityTradeService.buffer(s);}b.enabled(enable,actor.getUUID());}
        case "MASTER_POLICY"->{UUID policy=q.hasUUID("Selected")&&b.policy(q.getUUID("Selected")).isPresent()?q.getUUID("Selected"):MasterCityTradeService.stable("policy/"+actor.getUUID()+"/"+q.getUUID("Request"));ItemStack item;if(v.getString("Item").equalsIgnoreCase("hand"))item=actor.getMainHandItem().copyWithCount(1);else{var key=ResourceLocation.parse(v.getString("Item"));if(!BuiltInRegistries.ITEM.containsKey(key))throw new IllegalArgumentException("master_item_unknown");item=new ItemStack(BuiltInRegistries.ITEM.get(key));}if(item.isEmpty())throw new IllegalArgumentException("master_item_unknown");b.policy(new MasterCityTradeBook.Policy(policy,v.getString("Name"),(CompoundTag)item.save(s.registryAccess()),MasterCityTradeBook.Direction.valueOf(v.getString("Direction")),integer(v,"Target"),integer(v,"Maximum"),integer(v,"Batch"),integer(v,"Quota"),number(v,"Price"),number(v,"SellPrice"),number(v,"DispatchFee"),Boolean.parseBoolean(v.getString("Automatic")),v.getString("Partner"),Math.multiplyExact(number(v,"DelayMinutes"),60_000),Math.multiplyExact(number(v,"DurationHours"),3_600_000)),actor.getUUID());}
        case "MASTER_RUN"->{MasterCityTradeService.reconcile(s);MasterCityTradeService.run(s,actor.getUUID());}
        case "MASTER_CONTRACT_CLOSE"->MasterCityTradeService.closeContract(actor,q.getUUID("Selected"));
        case "MASTER_IMPORT_CLOSE"->MasterCityTradeService.closeImportListing(actor,q.getUUID("Selected"));
        case "MASTER_IMPORT_RECONCILE"->MasterCityTradeService.confirmImport(s,q.getUUID("Selected"),actor.getUUID());
        case "MASTER_IMPORT_ABANDON"->MasterCityTradeService.abandonImport(actor,q.getUUID("Selected"),v.getString("Reason"));
        case "CONTRACT_SUPPLY"->{if(!q.hasUUID("QuoteToken"))throw new IllegalArgumentException("delivery_quote_expired");MasterCityTradeService.supply(actor,q.getUUID("Selected"),v,q.getUUID("Request"),q.getUUID("QuoteToken"));}
        default->throw new IllegalArgumentException("master_action_unknown");}}
    private static ListTag importFacts(MasterCityTradeBook.ImportBatch batch){var facts=new ListTag();var state=new CompoundTag();state.putString("LabelKey","ccec.center.master.import_batch");state.putString("ValueKey","ccec.center.master.import_state."+batch.state());facts.add(state);if(!batch.problem().isBlank()){var problem=new CompoundTag();problem.putString("LabelKey","ccec.center.master.diagnostics");if(batch.problem().matches("master_[a-z_]+"))problem.putString("ValueKey","ccec.center.error."+batch.problem());else if(batch.problem().equals("physical receipt pending reconciliation"))problem.putString("ValueKey","ccec.center.master.import_waiting");else problem.putString("Value",batch.problem());facts.add(problem);}return facts;}
    private static void decorateForms(ListTag forms){for(Tag raw:forms){var form=(CompoundTag)raw;if(!form.getString("Action").equals("MASTER_POLICY"))continue;for(Tag f:form.getList("Fields",10)){var field=(CompoundTag)f;String key=field.getString("Key");field.putString("LabelKey","ccec.center.master.field."+key);field.putString("HintKey","ccec.center.master.hint."+key);if(field.getString("Kind").equals("number"))field.putLong("Min",Set.of("Target","DispatchFee","DelayMinutes").contains(key)?0:1);}}}
    private static UUID id(CompoundTag t,String key){return UUID.fromString(t.getString(key));}private static long number(CompoundTag t,String key){return Long.parseLong(t.getString(key));}private static int integer(CompoundTag t,String key){return Math.toIntExact(number(t,key));}
    private static CompoundTag row(UUID id,String kind,String name,String status,String detail){var t=CenterService.row(id,name,detail,status);t.putString("Kind",kind);t.putBoolean("Manage",kind.startsWith("master_"));return t;}
    private static void option(ListTag list,String value,String name){if(list.size()>=256)return;var t=new CompoundTag();t.putString("Value",value);t.putString("Name",name);list.add(t);}
    private static void detail(ListTag list,String name,String value){var labels=Map.ofEntries(Map.entry("Суточный бюджет","daily_budget"),Map.entry("Выделено контрактам","allocated"),Map.entry("Доступно для новых контрактов","remaining_budget"),Map.entry("В ограниченном счёте","held_cash"),Map.entry("Оплачено по поставкам","paid"),Map.entry("Возвращено в escrow","refunded"),Map.entry("Выведено продажами импорта","import_sink"),Map.entry("Создано импортом","created"),Map.entry("Физически принято по контрактам","received"),Map.entry("Город","city"),Map.entry("Склад","warehouse"),Map.entry("Таможенный буфер","buffer"),Map.entry("Диагностика","diagnostics"),Map.entry("Подключение","binding"),Map.entry("Целевой/максимальный запас","target_max"),Map.entry("Закупка/продажа","bid_ask"),Map.entry("Входящие поставки","inbound"),Map.entry("Физический остаток","stock"),Map.entry("Физический получатель","receiver"),Map.entry("Оплата перевозки","freight"),Map.entry("Срок","expires"),Map.entry("Остаток бюджета","contract_budget"));var values=Map.of("Заблокирован до сверки партии","buffer_locked","Доступен автоматике","buffer_open","Склад недоступен","warehouse_unavailable","Выберите город/склад, глядя на таможенный буфер","binding_help","Склад Моржеграда; товар остаётся собственностью города","goods_stay","Из выделенного бюджета контракта, в пределах резерва","freight_budget","Удалён","deleted");var t=new CompoundTag();String key=labels.get(name);t.putString("LabelKey","ccec.center.master."+(key==null?"audit":key));if(values.containsKey(value))t.putString("ValueKey","ccec.center.master."+values.get(value));else t.putString("Value",(key==null?name+": ":"")+value);t.putInt("Icon",4);list.add(t);}
}


